  MALB: "uacr", PLT: "platelets", WBC: "wbc", HGB: "hemoglobin", HB: "hemoglobin", BHB: "bhb", VPH: "ph", APH: "ph",
  PH: "ph", VPCO2: "pco2", APCO2: "pco2", PCO2: "pco2", LIPASE: "lipase", TROPI: "troponin", TNI: "troponin",
