const SALTS = new Set([
  "hydrochloride", "hcl", "hydrobromide", "sodium", "potassium", "calcium", "magnesium", "succinate", "tartrate",
  "besylate", "maleate", "mesylate", "trihydrate", "monohydrate", "dihydrate", "sulfate", "citrate", "fumarate",
